n.bookSourceComment:
/*1.2修复搜索 by:youke2580||游客2580
搜索有验证码，可复制链接在首页书架添加网址。以下代码勿动！❗️⚠️*/
try{
	var url=source.getKey(),
	so="/zhao/?keyword="+key,
	data=java.post(url+"/code",'',{});
	$=JSON.parse(data.body());
	let cid=$.CId,img=$.Image;
	code=java.getVerificationCode(img);
	so=url+`/zhao/?id=${cid}&keyword=${key}&code=${code}`;
	}catch(err){
		so=url;
		java.log(err)
	}finally{so}

